    function GetEntityTBL308(ent,a)
        hook.Run("GetEntityTBL308",ent,a)
    end
    function LoadEntity308(v)
        hook.Run("LoadEntity308",v)
    end
    function PostEntity308(v,ent)
        hook.Run("PostEntity308",v,ent)
    end
    function BlackListEntity308(v)
        hook.Run("BlackListEntity308",v)
    end
    local specials={}
    function AddSpecial308(cla,save,load,a)
        specials[cla]={save=save or function() end,load=load or function() end,a=a or ""}
    end
    function AddSpecialAlias308(cla,cla2)
        specials[cla]=specials[cla2]
    end
    AddSpecial308("gmod_lamp",
    function(ent,tbl)
        tbl.LAMP_Texture=ent.Texture
        tbl.LAMP_KeyDown=ent.KeyDown
        tbl.LAMP_fov=ent.fov
        tbl.LAMP_distance=ent.distance
        tbl.LAMP_r=ent.r
        tbl.LAMP_g=ent.g
        tbl.LAMP_b=ent.b
        tbl.LAMP_brightness=ent.brightness
    end,
    function(tbl,ent)
        ent:SetFlashlightTexture(tbl.LAMP_Texture)
        ent:SetLightFOV(tbl.LAMP_fov)
        ent:SetColor(Color(tbl.LAMP_r,tbl.LAMP_g,tbl.LAMP_b,255))
        ent:SetDistance(tbl.LAMP_distance)
        ent:SetBrightness(tbl.LAMP_brightness)
        ent:Switch(true)
        ent.Texture=tbl.LAMP_Texture
        ent.fov=tbl.LAMP_fov
        ent.distance=tbl.LAMP_distance
        ent.r=tbl.LAMP_r
        ent.g=tbl.LAMP_g
        ent.b=tbl.LAMP_b
        ent.brightness=tbl.LAMP_brightness
    end
    )
    AddSpecial308("prop_vehicle_jeep",function(ent,tbl)
        if(not ent.VehicleTable)then return end
        tbl.VName=ent.VehicleName
        tbl.VTbl=ent.VehicleTable
        tbl.ClassOverride=ent.ClassOverride
    end,function(tbl,ent)
        if (ent:GetModel()=="models/buggy.mdl") then ent:SetKeyValue("vehiclescript","scripts/vehicles/jeep_test.txt") end
        if(tbl.VehicleTable and tbl.VTbl.KeyValues)then
            for i,v in pairs(tbl.VTbl.KeyValues)do
                ent:SetKeyValue(i,v)
            end
        end
        --ent:Spawn()
        ent:Activate()
        ent:SetVehicleClass(tbl.VName)
        ent.VehicleName=tbl.VName
        ent.VehicleTable=tbl.VTbl
        ent.ClassOverride=tbl.ClassOverride
    end)
    AddSpecialAlias308("prop_vehicle_airboat","prop_vehicle_jeep")
    AddSpecialAlias308("prop_vehicle_prisoner_pod","prop_vehicle_jeep")
    AddSpecial308("NPC",function(ent,tbl)
        if(ent.Equipment)then
            tbl.Equipment=ent.Equipment
        end
    end,
    function(tbl,ent)
        if(tbl.Equipment)then
            ent:SetKeyValue("additionalequipment",tbl.Equipment)
            ent.Equipment=tbl.Equipment
        end
        ent:Activate()
    end)
    AddSpecial308("prop_effect",function(ent,tbl)
        tbl.IsEffect=true
        tbl.classname="prop_dynamic"
        tbl.mdl=ent.AttachedEntity:GetModel()
    end,
    function(tbl,ent)
        ent:SetMoveType(MOVETYPE_NONE)
        ent:SetCollisionGroup(COLLISION_GROUP_DEBRIS)
        ent:SetNotSolid(true)
    end,"IsEffect")

    AddSpecial308("prop_ragdoll",function(ent,tbl)
        tbl.rag={}
        for i=0,ent:GetPhysicsObjectCount()-1 do
            local phy=ent:GetPhysicsObjectNum(i)
            if(IsValid(phy))then
                tbl.rag[i]={pos=phy:GetPos(),ang=phy:GetAngles()}
            end
        end
    end,
    function(tbl,ent)
        if(tbl.rag)then
            for i,v in pairs(tbl.rag)do
                local phy=ent:GetPhysicsObjectNum(i)
                if(IsValid(phy))then
                    phy:SetPos(v.pos)
                    phy:SetAngles(v.ang)
                end
            end
        end
    end)

    hook.Add("GetEntityTBL308","special",function(ent,a)
        local cla=a.classname
        if(specials[cla])then
            specials[cla].save(ent,a)
        end
        local typ=type(ent)
        if(specials[typ])then
            specials[typ].save(ent,a)
        end
    end)
    hook.Add("PostEntity308","special",function(v,ent)
        local cla=ent:GetClass()
        if(specials[cla])then
            specials[cla].load(v,ent)
        end
        local typ=type(ent)
        if(specials[typ])then
            specials[typ].load(v,ent)
        end
        for i,s in pairs(specials)do
            if(ent[s.a])then
                s.load(v,ent)
            end
        end
    end)
    function LoadJsonEnt308(str,enttbl)
        local tbl=util.JSONToTable(str,true,false)
        local blacklist={}
        local enttbl=enttbl or {}
        for i,v in ipairs(tbl)do
            if(LoadEntity308)then
                LoadEntity308(v)
            end
            if(not blacklist[v.classname])then
                local ent=ents.Create(v.classname)
                if(IsValid(ent))then
                    enttbl[#enttbl+1]=ent
                    ent:SetPos(v.pos)
                    ent:SetAngles(v.ang)
                    ent:SetModel(v.mdl)
                    ent:Spawn()
                    ent:Activate()
                    ent:SetMaterial(v.mat)
                    ent:SetColor(Color(v.col.r,v.col.g,v.col.b,v.col.a))
                    ent:SetTable(table.Merge(ent:GetTable(),v.tbl))
                    ent.dt=table.Merge(ent.dt,v.dt)
                    if(IsValid(ent:GetPhysicsObject()))then
                        if(v.frozen)then
                            ent:GetPhysicsObject():EnableMotion(false)
                        end
                    elseif(v.frozen)then
                        --Do your thing to freeze it.
                        --Like overriding the SetPos and SetAngles
                        --Or something i dont know.
                    end
                    if(v.nothink)then
                        ent:NextThink(CurTime()*5)
                    end
                    if(v.hp)then
                        ent:SetHealth(v.hp)
                    end
                    if(v.mhp)then
                        ent:SetMaxHealth(v.hp)
                    end
                    if(v.NPCWEP)then
                        ent:Give(v.NPCWEP)
                    end
                    if(PostEntity308)then
                        PostEntity308(v,ent)
                    end
                else
                    if(BlackListEntity308)then
                        if(BlackListEntity308(v)==true)then
                            continue
                        end
                    end
                    blacklist[v.classname]=true
                end
            end
        end
        return enttbl
    end
else
    screenclicker308=screenclicker308 or false
    TOPVIEW308=false
    TOPVIEW308offset=Vector(0,0,0)
    TOPVIEW308offsetang=Angle()
    TOPVIEW308_worldclick=false
    TOPVIEW308_ortho = false
    local TOPVIEW308_WorldClickPanel
    concommand.Add("wb3_debug_forcetopview",function(_,_,args)
        TOPVIEW308=tobool(args[1])
        if(args[2] and args[3] and args[4])then
            TOPVIEW308offset=Vector(tonumber(args[2]) or 0,tonumber(args[3]) or 0,tonumber(args[4]) or 0)
        end
        if(args[5] and args[6] and args[7])then
            TOPVIEW308offsetang=Angle(tonumber(args[5]) or 0,tonumber(args[6]) or 0,tonumber(args[7]) or 0)
        end
        if args[8] then 
            TOPVIEW308_ortho = tobool(args[8])
        end
    end)
    local renderpos=Vector()
    local renderang=Angle()
    local renderfov=0
    hook.Add("CalcView","TopView",function(ply,origin,angles,fov)
        if(TOPVIEW308)then
            if(TOPVIEW308originbase)then
                origin=TOPVIEW308originbase
            end
            renderpos=origin+Vector(0,0,200)+TOPVIEW308offset
            renderang=Angle(90,0,0)+TOPVIEW308offsetang
            --print(fov)
            renderfov=fov
            local tbl = {angles=Angle(90,0,0)+TOPVIEW308offsetang,origin=origin+Vector(0,0,200)+TOPVIEW308offset,drawviewer=true}
            if TOPVIEW308_ortho then 
                local hw,hh = ScrW() * 0.5,ScrH() * 0.5
                tbl.ortho = {
                    left = -hw,
                    right = hw,
                    top = -hh,
                    bottom = hh
                }
            end
            return tbl
        end
    end)
    local w=IN_FORWARD
    local s=IN_BACK
    local a=IN_MOVELEFT
    local d=IN_MOVERIGHT
    local angles={
        [w]=Angle(0,0,0),
        [s]=Angle(0,-180,0),
        [d]=Angle(0,-90,0),
        [a]=Angle(0,90,0),
        [w+d]=Angle(0,-45,0),
        [w+a]=Angle(0,45,0),
        [s+d]=Angle(0,-180+45,0),
        [s+a]=Angle(0,-180+-45,0),
    }
    hook.Add("CreateMove","TopViewMove",function(cmd)
        if(TOPVIEW308)then
            gui.EnableScreenClicker(true)
            screenclicker308=true
            local stopafterws
            local x,y=input.GetCursorPos()
            if(cmd:KeyDown(w))then
                if(cmd:KeyDown(d))then
                    cmd:SetForwardMove(cmd:GetSideMove())
                    cmd:SetSideMove(0)
                    cmd:SetViewAngles(angles[w+d])
                    stopafterws=true
                elseif(cmd:KeyDown(a))then
                    cmd:SetForwardMove(-cmd:GetSideMove())
                    cmd:SetSideMove(0)
                    cmd:SetViewAngles(angles[w+a])
                    stopafterws=true
                else
                    cmd:SetViewAngles(angles[w])
                end
            end
            if(cmd:KeyDown(s))then
                if(cmd:KeyDown(d))then
                    cmd:SetForwardMove(cmd:GetSideMove())
                    cmd:SetSideMove(0)
                    cmd:SetViewAngles(angles[s+d])
                    stopafterws=true
                elseif(cmd:KeyDown(a))then
                    cmd:SetForwardMove(-cmd:GetSideMove())
                    cmd:SetSideMove(0)
                    cmd:SetViewAngles(angles[s+a])
                    stopafterws=true
                else
                    cmd:SetViewAngles(angles[s])
                    cmd:SetForwardMove(-cmd:GetForwardMove())
                end
            end
            if(stopafterws)then return end
            if(cmd:KeyDown(d))then
                cmd:SetViewAngles(angles[d])
                cmd:SetForwardMove(cmd:GetSideMove())
                cmd:SetSideMove(0)
            end
            if(cmd:KeyDown(a))then
                cmd:SetViewAngles(angles[a])
                cmd:SetForwardMove(-cmd:GetSideMove())
                cmd:SetSideMove(0)
            end
        elseif(screenclicker308)then
            gui.EnableScreenClicker(false)
            screenclicker308=false
            TOPVIEW308offsetang=angle_zero
            TOPVIEW308offset=vector_zero
            TOPVIEW308originbase=nil
        end
    end)
    Settings308=Settings308 or {}
    function Add308Setting(name,convar,type)
        local a={cvar=convar,type=type}
        if(convar)then
            a.description=convar:GetHelpText()
        end
        Settings308[name]=a
        return a
    end
    function Open308Settings()
        if IsValid(Settings308_menu)then Settings308_menu:Remove() end
        local frame=vgui.Create("DFrame")
        frame:SetSize(ScrW()*0.65,ScrH()*0.65)
        frame:Center()
        frame:MakePopup()
        frame:SetTitle("308's Simple settings!")
        Settings308_menu=frame
        local list=vgui.Create("DScrollPanel",frame)
        list:Dock(FILL)
        local a=table.GetKeys(Settings308)
        local Settings308=Settings308
        local s=Settings308
        table.sort(a,function(a,b) return s[a].type<s[b].type end)
        for i,v in ipairs(a)do
            local i,v=v,Settings308[v]
            if(v.type==TYPE_NUMBER)then
                local cvar=v.cvar
                local it=vgui.Create("DNumSlider")
                it:SetMin(cvar:GetMin())
                it:SetMax(cvar:GetMax())
                it:SetValue(cvar:GetFloat())
                it:SetDecimals(1)
                it:DockMargin(5,5,5,5)
                it:Dock(TOP)
                it:SetText(v.description)
                it.cvarname=i
                it.OnValueChanged = function(self,value)
                    RunConsoleCommand(self.cvarname,value)
                end
                list:AddItem(it)
            elseif(v.type==TYPE_BOOL)then
                local cvar=v.cvar
                local it=vgui.Create("DCheckBoxLabel")
                it:SetValue(cvar:GetBool())
                it.cvarname=i
                it.OnChange = function(self,value)
                    RunConsoleCommand(self.cvarname,value and 1 or 0)
                end
                it:DockMargin(5,5,5,5)
                it:Dock(TOP)
                it:SetText(v.description)
                it:SizeToContents()
                list:AddItem(it)
            elseif(v.type==TYPE_COLOR)then
                if(not v.r or not v.g or not v.b)then continue end
                local label=vgui.Create("DLabel")
                label:Dock(TOP)
                label:DockMargin(5,5,5,5)
                label:SetText(v.description)
                label:SizeToContents()
                list:AddItem(label)
                local it=vgui.Create("DColorMixer")
                it:SetConVarR(v.r)
                it:SetConVarG(v.g)
                it:SetConVarB(v.b)
                it:DockMargin(5,5,5,5)
                it:Dock(TOP)
                it:SetText(v.description)
                it:SizeToContents()
                it:SetAlphaBar(false)
                list:AddItem(it)
            end
        end
    end
    concommand.Add("open308settings",Open308Settings)
end